const importId = 'basemap';
const config = (typeof map.getConfig === 'function' && map.getConfig(importId)) || {};
let laneKeys = Object.keys(config).filter((key) => /lane/i.test(key));
if (laneKeys.length === 0) laneKeys = ['showLaneMarkings', 'showLanes'];
laneKeys.forEach((key) => {
  try {
    map.setConfigProperty(importId, key, true);
  } catch (err) {
    console.warn(`Could not set ${key}:`, err);
  }
});

